// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ResearchNode) predicate.ResearchNode {
	return predicate.ResearchNode(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ResearchNode) predicate.ResearchNode {
	return predicate.ResearchNode(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ResearchNode) predicate.ResearchNode {
	return predicate.ResearchNode(sql.NotPredicates(p))
}
